exports.tool_call = function(args) {
  const { departement, commune, risk_type, search_term } = JSON.parse(args);

  // Fonction interne pour normaliser
  function normalize(text) {
    if (!text) return '';
    return text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  }

  // Vérifier département
  if (!departement || !DDRM_DATA[departement]) {
    return JSON.stringify({
      error: "Département invalide",
      departement_demande: departement,
      departements_disponibles: Object.keys(DDRM_DATA)
    }, null, 2);
  }

  const deptInfo = DDRM_DATA[departement];
  const deptData = deptInfo.data;

  if (commune) {
    const communeNorm = normalize(commune);
    let foundCommune = null;
    
    for (let key in deptData) {
      if (normalize(key) === communeNorm) {
        foundCommune = key;
        break;
      }
    }

    if (!foundCommune) {
      return JSON.stringify({
        error: "Commune non trouvée",
        commune_demandee: commune
      }, null, 2);
    }

    let refs = deptData[foundCommune].refs;

    // Filtrer
    if (risk_type) {
      const riskNorm = normalize(risk_type);
      refs = refs.filter(ref => normalize(ref.risque).includes(riskNorm));
    }
    if (search_term) {
      const searchNorm = normalize(search_term);
      refs = refs.filter(ref => 
        normalize(ref.section).includes(searchNorm) || 
        normalize(ref.texte).includes(searchNorm)
      );
    }

    return JSON.stringify({
      departement: departement + " - " + deptInfo.nom,
      commune: foundCommune,
      risques: deptData[foundCommune].risques,
      nb_refs: refs.length,
      refs: refs
    }, null, 2);
  }

  // Tout le département
  let allCommunes = [];
  
  for (let communeName in deptData) {
    let refs = deptData[communeName].refs;

    if (risk_type) {
      const riskNorm = normalize(risk_type);
      refs = refs.filter(ref => normalize(ref.risque).includes(riskNorm));
    }
    if (search_term) {
      const searchNorm = normalize(search_term);
      refs = refs.filter(ref => 
        normalize(ref.section).includes(searchNorm) || 
        normalize(ref.texte).includes(searchNorm)
      );
    }

    if (refs.length > 0) {
      allCommunes.push({
        commune: communeName,
        risques: deptData[communeName].risques,
        nb_refs: refs.length,
        refs: refs
      });
    }
  }

  return JSON.stringify({
    departement: departement + " - " + deptInfo.nom,
    nb_communes: allCommunes.length,
    communes: allCommunes
  }, null, 2);
};"}}},"user-agent-details":null,"origin-details":null,"instance-number":0,"instance-name":"otoroshi","instance-zone":"local","instance-region":"local","instance-dc":"local","instance-provider":"local","instance-rack":"local","cluster-mode":"Off","cluster-name":"none"}

