        },
        {
          "type": "texte",
          "valeur": "le  repérage des zones inondables réalisé dans le cadre des Atlas des Zones Inondables (AZI) d'une part et des Plans de Prévention des Risques inondation (PPRi) d'autre part,"
        },
        {
          "type": "texte",
          "valeur": "les modèles de prévision des crues du Service de Prévision des Crues (SPC)."
        }
