exports.tool_call = function(args) {
  const { commune, risk_type, search_term } = JSON.parse(args);

  function searchInSections(sections, term) {
    let results = [];
    const searchLower = term ? term.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '') : '';

    for (let section of sections) {
      const titreLower = section.titre.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
      let matchFound = false;

      // Cherche dans le titre
      if (searchLower && titreLower.includes(searchLower)) {
        matchFound = true;
      }

      // Cherche dans le contenu
      if (!matchFound && searchLower && section.contenu && section.contenu.length > 0) {
        for (let item of section.contenu) {
          if (item.valeur) {
            const valeurLower = item.valeur.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
            if (valeurLower.includes(searchLower)) {
              matchFound = true;
              break;
            }
          }
        }
      }

      // Si trouvé, ajoute le résultat
      if (matchFound) {
        results.push({
          titre: section.titre,
          contenu: section.contenu.slice(0, 5) // Limite à 5 éléments
        });
      }

      // Recherche récursive dans les sous-sections
      if (section.sous_sections && section.sous_sections.length > 0) {
        results = results.concat(searchInSections(section.sous_sections, term));
      }
    }
    return results;
  }

  const searchQuery = risk_type || search_term || commune || "";
  const results = searchInSections(DDRM_DATA.sous_sections, searchQuery);

return JSON.stringify({
  departement: "Savoie (73)",
  recherche: searchQuery,
  nb_resultats: results.length,
  resultats: results.slice(0, 10)
}, null, 2);
