        },
        {
          "type": "texte",
          "valeur": "la présence ou non de victimes"
        },
        {
          "type": "texte",
          "valeur": ">"
        },
        {
          "type": "texte",
          "valeur": "Si un nuage ou des fumées viennent vers vous :"
        },
