      "titre": "1.3. Les conséquences sur les personnes et les biens",
      "niveau": 1,
      "contenu": [
        {
          "type": "texte",
          "valeur": "L'onde de submersion produite, l'inondation qui s'en suit et les matériaux issus de l'ouvrage et de l'érosion de la vallée peuvent occasionner des dommages considérables."
        }
      ],
      "sous_sections": []
