    {
      "titre": "7. Les consignes individuelles de sécurité spécifiques",
      "niveau": 1,
      "contenu": [
        {
          "type": "texte",
          "valeur": "> Connaitre  le  signal  d'alerte  et  les  consignes  de  confinement"
        },
        {
          "type": "texte",
          "valeur": ">"
        },
        {
          "type": "texte",
          "valeur": "Si vous êtes témoin d'un accident :"
        },
        {
          "type": "texte",
          "valeur": "donner l'alerte aux pompiers (18 ou 112), à la police ou à la gendarmerie (17 ou 112), en précisant :"
        },
        {
          "type": "texte",
